#[test]
fn hide_entity_from_is_generated_and_exact() {
    let lua = lua();
    let mut host = gen_host(false, false);
    let t = args(
        &lua,
        &[
            mlua::Value::String(
                lua.create_string("123e4567-e89b-12d3-a456-426614174000")
                    .unwrap(),
            ),
            mlua::Value::Integer(3),
            mlua::Value::Boolean(true),
        ],
    );
    run_generated_action(&mut host, "hide_entity_from", &t)
        .unwrap()
        .unwrap();
    assert_eq!(
        host.logged(),
        ["hide_entity_from 24249434048109030647017182301789831168 3 true"]
    );
    {
        let mut host = gen_host(false, false);
        let t = args(
            &lua,
            &[
                mlua::Value::String(
                    lua.create_string("123e4567-e89b-12d3-a456-426614174000")
                        .unwrap(),
                ),
                mlua::Value::Integer(-1),
                mlua::Value::Boolean(true),
            ],
        );
        run_generated_action(&mut host, "hide_entity_from", &t)
            .unwrap()
            .unwrap();
        assert_eq!(
            host.logged(),
            ["hide_entity_from 24249434048109030647017182301789831168 0 true"]
        );
    }
    {
        let mut host = gen_host(false, false);
        let t = args(
            &lua,
            &[
                mlua::Value::String(
                    lua.create_string("123e4567-e89b-12d3-a456-426614174000")
                        .unwrap(),
                ),
                mlua::Value::Integer(300),
                mlua::Value::Boolean(true),
            ],
        );
        run_generated_action(&mut host, "hide_entity_from", &t)
            .unwrap()
            .unwrap();
        assert_eq!(
            host.logged(),
            ["hide_entity_from 24249434048109030647017182301789831168 300 true"]
        );
    }
    {
        let mut host = gen_host(false, false);
        let t = args(
            &lua,
            &[
                mlua::Value::String(lua.create_string("ghost").unwrap()),
                mlua::Value::Integer(3),
                mlua::Value::Boolean(true),
            ],
        );
        run_generated_action(&mut host, "hide_entity_from", &t)
            .unwrap()
            .unwrap();
        assert!(
            host.logged().is_empty(),
            "an unresolvable player calls nothing"
        );
    }
    {
        let mut host = gen_host(false, false);
        let t = args(
            &lua,
            &[
                mlua::Value::String(
                    lua.create_string("123e4567-e89b-12d3-a456-426614174000")
                        .unwrap(),
                ),
                mlua::Value::Table(lua.create_table().unwrap()),
                mlua::Value::Boolean(true),
            ],
        );
        let err = run_generated_action(&mut host, "hide_entity_from", &t)
            .unwrap()
            .unwrap_err();
        let text = err.to_string();
        assert!(text.contains("hide_entity_from"), "{text}");
        assert!(text.contains("entity"), "{text}");
    }
}

