#[test]
fn teleport_vehicle_is_generated_and_exact() {
    let lua = lua();
    let mut host = gen_host(false, false);
    let t = args(
        &lua,
        &[
            mlua::Value::String(lua.create_string("ruby:gen1").unwrap()),
            mlua::Value::Integer(3),
            {
                let t = lua.create_table().unwrap();
                t.set("x", 1.5).unwrap();
                t.set("y", 2.5).unwrap();
                t.set("z", 3.5).unwrap();
                mlua::Value::Table(t)
            },
        ],
    );
    run_generated_action(&mut host, "teleport_vehicle", &t)
        .unwrap()
        .unwrap();
    assert_eq!(
        host.logged(),
        ["teleport_vehicle ruby:gen1 3 [1.5, 2.5, 3.5]"]
    );
    {
        let mut host = gen_host(false, false);
        let t = args(
            &lua,
            &[
                mlua::Value::String(lua.create_string("ruby:gen").unwrap()),
                mlua::Value::Integer(-1),
                {
                    let t = lua.create_table().unwrap();
                    t.set("x", 1.5).unwrap();
                    t.set("y", 2.5).unwrap();
                    t.set("z", 3.5).unwrap();
                    mlua::Value::Table(t)
                },
            ],
        );
        run_generated_action(&mut host, "teleport_vehicle", &t)
            .unwrap()
            .unwrap();
        assert_eq!(
            host.logged(),
            ["teleport_vehicle ruby:gen 0 [1.5, 2.5, 3.5]"]
        );
    }
    {
        let mut host = gen_host(false, false);
        let t = args(
            &lua,
            &[
                mlua::Value::String(lua.create_string("ruby:gen").unwrap()),
                mlua::Value::Integer(300),
                {
                    let t = lua.create_table().unwrap();
                    t.set("x", 1.5).unwrap();
                    t.set("y", 2.5).unwrap();
                    t.set("z", 3.5).unwrap();
                    mlua::Value::Table(t)
                },
            ],
        );
        run_generated_action(&mut host, "teleport_vehicle", &t)
            .unwrap()
            .unwrap();
        assert_eq!(
            host.logged(),
            ["teleport_vehicle ruby:gen 300 [1.5, 2.5, 3.5]"]
        );
    }
    {
        let mut host = gen_host(false, false);
        let t = args(
            &lua,
            &[
                mlua::Value::String(lua.create_string("ruby:gen1").unwrap()),
                mlua::Value::Integer(3),
                {
                    let t = lua.create_table().unwrap();
                    t.set("x", f64::NAN).unwrap();
                    t.set("y", 2.5).unwrap();
                    t.set("z", 3.5).unwrap();
                    mlua::Value::Table(t)
                },
            ],
        );
        let err = run_generated_action(&mut host, "teleport_vehicle", &t)
            .unwrap()
            .unwrap_err();
        let text = err.to_string();
        assert!(text.contains("teleport_vehicle.pos"), "{text}");
    }
    {
        let mut host = gen_host(false, false);
        let t = args(
            &lua,
            &[
                mlua::Value::String(lua.create_string("ruby:gen1").unwrap()),
                mlua::Value::Integer(3),
                {
                    let t = lua.create_table().unwrap();
                    t.set("x", 1.5).unwrap();
                    t.set("y", 2.5).unwrap();
                    mlua::Value::Table(t)
                },
            ],
        );
        let err = run_generated_action(&mut host, "teleport_vehicle", &t)
            .unwrap()
            .unwrap_err();
        let text = err.to_string();
        assert!(text.contains("teleport_vehicle.pos"), "{text}");
    }
    {
        let mut host = gen_host(false, false);
        let t = args(
            &lua,
            &[
                mlua::Value::Table(lua.create_table().unwrap()),
                mlua::Value::Integer(3),
                {
                    let t = lua.create_table().unwrap();
                    t.set("x", 1.5).unwrap();
                    t.set("y", 2.5).unwrap();
                    t.set("z", 3.5).unwrap();
                    mlua::Value::Table(t)
                },
            ],
        );
        let err = run_generated_action(&mut host, "teleport_vehicle", &t)
            .unwrap()
            .unwrap_err();
        let text = err.to_string();
        assert!(text.contains("teleport_vehicle"), "{text}");
        assert!(text.contains("dimension"), "{text}");
    }
}

