#[test]
fn world_seed_is_generated_and_exact() {
    let lua = lua();
    let h = gen_host(false, false);
    let v = generated_read(&lua, &h, "world_seed", rest(&lua, &[]))
        .unwrap()
        .unwrap();
    assert!(matches!(v, mlua::Value::Integer(_)), "{v:?}");
    assert_eq!(h.logged(), ["world_seed"]);
    {
        let h = gen_host(true, false);
        let v = generated_read(&lua, &h, "world_seed", rest(&lua, &[]))
            .unwrap()
            .unwrap();
        assert!(matches!(v, mlua::Value::Nil), "{v:?}");
    }
}
